/**
 * Daily briefing — one per firm per day, generated by the daily pipeline (or
 * on first open), stored in `daily_briefings`, emailed with the digest, and
 * shown on /briefing and inside the assistant.
 */
import { llmComplete } from "@/lib/ai/complete";
import type { Json } from "@/lib/db/database.types";
import { listLaneOpportunities } from "@/lib/db/lane-opportunities";
import { listHotOpportunities } from "@/lib/db/opportunities";
import { getSupabaseAdmin, isDatabaseConfigured } from "@/lib/db/supabase-admin";
import { workspaceLanes } from "@/lib/firms/lanes";
import { buildFirmSystemPrompt } from "@/lib/firms/prompt";
import type { FirmProfile } from "@/lib/firms/types";
import { logger } from "@/lib/logger";

export interface BriefingEntry {
  id: string;
  timestamp: string;
  headline: string;
  body: string;
  category: "market" | "deadline" | "hot" | "insight" | "pursuit" | "automation";
  opportunity_id?: string;
  actions: { label: string; href: string }[];
}

export interface DailyBriefingData {
  id?: string;
  briefing_date: string;
  generated_at: string;
  industry_pulse: string;
  ai_generated: boolean;
  hot_count: number;
  deadline_this_week: number;
  pending_approvals: number;
  entries: BriefingEntry[];
}

export function briefingDate(now = new Date()): string {
  return now.toISOString().slice(0, 10);
}

function fmt(iso: string | null | undefined) {
  return iso ? new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "TBD";
}

async function assembleBriefing(firm: FirmProfile): Promise<DailyBriefingData> {
  const now = new Date();
  const generatedAt = now.toISOString();
  const supabase = getSupabaseAdmin();
  const weekEnd = new Date(now.getTime() + 7 * 86_400_000).toISOString();

  const lanes = workspaceLanes(firm).filter((l) => l.id !== "federal");
  const [hot, laneCounts, pursuitsRes, pendingRes, recentEventsRes] = await Promise.all([
    listHotOpportunities(firm.id, 12),
    Promise.all(
      lanes.map(async (l) => ({ lane: l, items: await listLaneOpportunities(firm, l.id, { limit: 40 }).catch(() => []) })),
    ),
    supabase.from("watchlists").select("opportunity_id, pursuit_stage, user_email").eq("firm_id", firm.id),
    supabase
      .from("automation_events")
      .select("id", { count: "exact", head: true })
      .eq("firm_id", firm.id)
      .eq("status", "pending_approval"),
    supabase
      .from("automation_events")
      .select("opportunity_id, kind, ai_summary, created_at, automation_id")
      .eq("firm_id", firm.id)
      .gte("created_at", new Date(now.getTime() - 86_400_000).toISOString())
      .order("created_at", { ascending: false })
      .limit(10),
  ]);

  // Deadlines this week across the firm's pursuits and its best-fit pool.
  const pursuitIds = (pursuitsRes.data ?? []).map((p) => p.opportunity_id);
  const candidateIds = [...new Set([...pursuitIds, ...hot.map((h) => h.id)])];
  const { data: deadlineRows } = candidateIds.length
    ? await supabase
        .from("opportunities")
        .select("id, title, agency_name, response_deadline, naics")
        .in("id", candidateIds)
        .gte("response_deadline", generatedAt)
        .lte("response_deadline", weekEnd)
        .order("response_deadline", { ascending: true })
        .limit(10)
    : { data: [] as { id: string; title: string; agency_name: string | null; response_deadline: string | null; naics: string | null }[] };

  const stageCounts = new Map<string, number>();
  for (const p of pursuitsRes.data ?? []) stageCounts.set(p.pursuit_stage, (stageCounts.get(p.pursuit_stage) ?? 0) + 1);
  const pending = pendingRes.count ?? 0;

  const laneSummary = laneCounts
    .filter((l) => l.items.length > 0)
    .map((l) => `${l.items.length >= 40 ? "40+" : l.items.length} open in ${l.lane.label}`)
    .join(", ");

  const fallbackPulse = [
    `${hot.length} high-fit federal and SLED opportunities are open for ${firm.shortName}.`,
    laneSummary ? `Across your workspace lanes: ${laneSummary}.` : "",
    deadlineRows?.length ? `${deadlineRows.length} deadline(s) land this week.` : "",
    pending ? `${pending} automation item(s) are waiting for your approval.` : "",
  ]
    .filter(Boolean)
    .join(" ");

  const entries: BriefingEntry[] = [];

  for (const opp of hot.slice(0, 5)) {
    entries.push({
      id: `hot-${opp.id}`,
      timestamp: generatedAt,
      headline: opp.title,
      body: `${opp.agency_name ?? "Agency TBD"} · Fit ${opp.fit_score ?? "—"}% · ${(opp.go_no_go ?? "review").replace("_", " ")} · Due ${fmt(opp.response_deadline)}. ${opp.score_rationale ?? ""}`.trim(),
      category: "hot",
      opportunity_id: opp.id,
      actions: [
        { label: "Open workspace", href: `/opportunities/${opp.id}` },
        { label: "Analyze in chat", href: `/explore?ask=${encodeURIComponent(`Analyze ${opp.title} for ${firm.shortName} pursuit fit`)}` },
      ],
    });
  }

  for (const lane of laneCounts) {
    const top = lane.items.filter((i) => (i.fit_score ?? 0) >= 50).slice(0, 2);
    if (top.length === 0) continue;
    entries.push({
      id: `lane-${lane.lane.id}`,
      timestamp: generatedAt,
      headline: `${lane.lane.label}: ${lane.items.length >= 40 ? "40+" : lane.items.length} open`,
      body: `Best fits: ${top.map((t) => `${t.title} (fit ${t.fit_score})`).join("; ")}.`,
      category: "market",
      actions: [{ label: `Open ${lane.lane.label}`, href: lane.lane.href }],
    });
  }

  for (const row of deadlineRows ?? []) {
    const isPursuit = pursuitIds.includes(row.id);
    entries.push({
      id: `deadline-${row.id}`,
      timestamp: row.response_deadline ?? generatedAt,
      headline: `${isPursuit ? "Pursuit deadline" : "Deadline approaching"} — ${row.title}`,
      body: `${row.agency_name ?? "Agency TBD"} · Due ${new Date(row.response_deadline!).toLocaleString("en-US")}${row.naics ? ` · NAICS ${row.naics}` : ""}`,
      category: "deadline",
      opportunity_id: row.id,
      actions: [{ label: "View opportunity", href: `/opportunities/${row.id}` }],
    });
  }

  if (stageCounts.size) {
    entries.push({
      id: "pursuits",
      timestamp: generatedAt,
      headline: "Pursuit pipeline",
      body: [...stageCounts.entries()].map(([s, n]) => `${n} ${s.replace("_", " ")}`).join(" · "),
      category: "pursuit",
      actions: [{ label: "Open pursuits", href: "/watchlist" }],
    });
  }

  if (pending || recentEventsRes.data?.length) {
    entries.push({
      id: "automations",
      timestamp: generatedAt,
      headline: pending ? `${pending} automation item(s) need approval` : "Automation activity",
      body: `${recentEventsRes.data?.length ?? 0} item(s) flagged by your agents in the last 24 hours.`,
      category: "automation",
      actions: [{ label: "Review automations", href: "/automations" }],
    });
  }

  let pulse = fallbackPulse;
  let aiGenerated = false;
  try {
    const { text } = await llmComplete({
      system: buildFirmSystemPrompt(firm),
      maxTokens: 450,
      userPrompt: [
        `Write today's capture briefing "industry pulse" for ${firm.legalName} in 3-5 sentences of plain prose (no markdown, no lists).`,
        "Lead with the single most important action today. Mention specific opportunities by title when useful. Be concrete; do not invent facts.",
        `Data: ${JSON.stringify({
          hot: hot.slice(0, 6).map((h) => ({ title: h.title, agency: h.agency_name, fit: h.fit_score, due: h.response_deadline })),
          lanes: laneCounts.map((l) => ({ lane: l.lane.label, open: l.items.length >= 40 ? "40+" : l.items.length, best_fit: l.items[0]?.title ?? null })),
          deadlines_this_week: (deadlineRows ?? []).map((d) => ({ title: d.title, due: d.response_deadline, pursuit: pursuitIds.includes(d.id) })),
          pursuit_stages: Object.fromEntries(stageCounts),
          automation_pending_approvals: pending,
        })}`,
      ].join("\n"),
    });
    const cleaned = text.replace(/[*#`]/g, "").trim();
    if (cleaned.length > 40) {
      pulse = cleaned.slice(0, 1500);
      aiGenerated = true;
    }
  } catch (error) {
    logger.warn("briefing.ai_failed", { firm: firm.slug, error: error instanceof Error ? error.message : String(error) });
  }

  entries.unshift({
    id: "pulse-today",
    timestamp: generatedAt,
    headline: "Industry pulse",
    body: pulse,
    category: "market",
    actions: [{ label: "Explore hot feed", href: "/explore" }],
  });

  entries.push({
    id: "insight-teaming",
    timestamp: generatedAt,
    headline: "Capture insight",
    body: "Review teaming partners before final go/no-go on large solicitations, and run the compliance checklist early on anything you intend to bid.",
    category: "insight",
    actions: [{ label: "View vendors", href: "/participants/vendors" }],
  });

  return {
    briefing_date: briefingDate(now),
    generated_at: generatedAt,
    industry_pulse: pulse,
    ai_generated: aiGenerated,
    hot_count: hot.length,
    deadline_this_week: deadlineRows?.length ?? 0,
    pending_approvals: pending,
    entries,
  };
}

/** Today's stored briefing for the firm, generating (and storing) it if missing. */
export async function getDailyBriefing(
  firm: FirmProfile,
  options: { regenerate?: boolean } = {},
): Promise<DailyBriefingData> {
  if (!isDatabaseConfigured()) {
    return {
      briefing_date: briefingDate(),
      generated_at: new Date().toISOString(),
      industry_pulse: "Connect Supabase and run the daily pipeline to activate your briefing.",
      ai_generated: false,
      hot_count: 0,
      deadline_this_week: 0,
      pending_approvals: 0,
      entries: [],
    };
  }
  const supabase = getSupabaseAdmin();
  const date = briefingDate();
  if (!options.regenerate) {
    const { data } = await supabase
      .from("daily_briefings")
      .select("id, content")
      .eq("firm_id", firm.id)
      .eq("briefing_date", date)
      .maybeSingle();
    if (data) return { ...(data.content as unknown as DailyBriefingData), id: data.id };
  }

  const briefing = await assembleBriefing(firm);
  const { data: saved, error } = await supabase
    .from("daily_briefings")
    .upsert(
      {
        firm_id: firm.id,
        briefing_date: date,
        content: briefing as unknown as Json,
        ai_summary: briefing.industry_pulse,
        provider: briefing.ai_generated ? "llm" : "rules",
      },
      { onConflict: "firm_id,briefing_date" },
    )
    .select("id")
    .single();
  if (error) logger.warn("briefing.store_failed", { firm: firm.slug, error: error.message });
  return { ...briefing, id: saved?.id };
}

export async function markBriefingEmailed(firmId: string, date = briefingDate()) {
  await getSupabaseAdmin()
    .from("daily_briefings")
    .update({ emailed_at: new Date().toISOString() })
    .eq("firm_id", firmId)
    .eq("briefing_date", date);
}

/** Back-compat for existing callers. */
export const buildDailyBriefing = (firm: FirmProfile) => getDailyBriefing(firm);
